package tr.kasadenge.app;
import android.database.*;import android.database.sqlite.*;import android.content.ContentValues;import org.json.*;import java.time.*;import java.util.*;
final class PosLedger {
 static void create(SQLiteDatabase d){d.execSQL("CREATE TABLE IF NOT EXISTS pos_totals (id TEXT PRIMARY KEY, data TEXT NOT NULL)");d.execSQL("CREATE TABLE IF NOT EXISTS pos_settlements (id TEXT PRIMARY KEY, data TEXT NOT NULL)");d.execSQL("CREATE TABLE IF NOT EXISTS pos_ledger_revisions (id INTEGER PRIMARY KEY AUTOINCREMENT, data TEXT NOT NULL)");}
 static JSONObject find(SQLiteDatabase d,String table,String id)throws Exception{try(Cursor c=d.rawQuery("SELECT data FROM "+table+" WHERE id=?",new String[]{id})){return c.moveToFirst()?new JSONObject(c.getString(0)):null;}}
 static void put(SQLiteDatabase d,String table,JSONObject r)throws Exception{ContentValues v=new ContentValues();v.put("id",r.getString("id"));v.put("data",r.toString());d.insertWithOnConflict(table,null,v,SQLiteDatabase.CONFLICT_REPLACE);}
 static JSONObject total(JSONObject in)throws Exception{String cash=CashDb.text(in,"cashId",80),date=CashDb.day(in);if(!cash.matches("[a-zA-Z0-9_-]+"))throw new Exception("Kasa Geçersiz.");long amount=CashDb.number(in,"total");if(amount==0)throw new Exception("Toplam POS Pozitif Olmalı.");return new JSONObject().put("id",cash+"_"+date+"_total").put("cashId",cash).put("cashName",CashDb.text(in,"cashName",60)).put("date",date).put("total",amount);}
 static JSONObject settlement(JSONObject in,JSONObject total,JSONObject debit)throws Exception{String kind=in.getString("kind"),bankDate=in.getString("bankDate");if(!kind.equals("debit"))throw new Exception("Kart Türü Geçersiz.");LocalDate b=LocalDate.parse(bankDate);if(!bankDate.equals(b.toString())||b.isAfter(LocalDate.now()))throw new Exception("Yatış Tarihi Geçersiz.");String date=b.minusDays(kind.equals("debit")?15:21).toString();boolean manual=in.optBoolean("manualDateLink",false)&&in.optString("reason","").trim().length()>=3;if((!date.equals(total.getString("date"))&&!manual)||!in.getString("cashId").equals(total.getString("cashId")))throw new Exception("Yatış Tarihi Bu İşlem Kaydıyla Eşleşmiyor.");long amount=CashDb.number(in,"amount");if(amount<1)throw new Exception("Yatan Tutar Pozitif Olmalı.");if(kind.equals("debit")&&amount>total.getLong("total"))throw new Exception("Debit Toplam POS Tutarını Aşamaz.");if(kind.equals("credit")&&debit==null)throw new Exception("Önce Yatan Debit Tutarını Girin.");return new JSONObject().put("id",total.getString("id")+"_"+kind).put("totalId",total.getString("id")).put("cashId",total.getString("cashId")).put("kind",kind).put("bankDate",bankDate).put("transactionDate",total.getString("date")).put("amount",amount).put("manualDateLink",manual);}
 static void checkRevision(JSONObject in,JSONObject old)throws Exception{if(old!=null&&(in.optInt("baseRevision")!=old.getInt("revision")||in.optString("reason","").trim().length()<3))throw new Exception("Kayıt Zaten Var. Güncel Kaydı Açıp Düzeltme Gerekçesini Yazın.");}
 static void save(SQLiteDatabase d,String table,JSONObject r,JSONObject old,JSONObject in)throws Exception{r.put("revision",old==null?1:old.getInt("revision")+1).put("savedAt",System.currentTimeMillis()).put("reason",in.optString("reason","").trim());if(old!=null){ContentValues v=new ContentValues();v.put("data",old.toString());d.insertOrThrow("pos_ledger_revisions",null,v);}put(d,table,r);}
 static JSONObject saveTotal(CashDb db,String raw)throws Exception{
  JSONObject in=new JSONObject(raw),r=total(in);boolean active=false;JSONArray boxes=db.settings().getJSONArray("cashboxes");for(int i=0;i<boxes.length();i++){JSONObject b=boxes.getJSONObject(i);if(b.getString("id").equals(r.getString("cashId"))&&b.optBoolean("active")&&b.optString("posMode").equals("total"))active=true;}if(!active)throw new Exception("Etkin Tek Toplam POS Kasası Gerekli.");SQLiteDatabase d=db.getWritableDatabase();d.beginTransaction();try{
   ensureNoDetailed(d,r);String original=in.optString("originalId",r.getString("id"));JSONObject old=find(d,"pos_totals",original),destination=find(d,"pos_totals",r.getString("id")),debit=find(d,"pos_settlements",original+"_debit");
   if(in.has("originalId")&&old==null)throw new Exception("Düzenlenen Toplam Kaydı Artık Yok.");if(old!=null&&!old.getString("cashId").equals(r.getString("cashId")))throw new Exception("Tarih Düzeltmesinde Kasa Değiştirilemez.");if(!original.equals(r.getString("id"))&&destination!=null)throw new Exception("Yeni Tarihte Bu Kasaya Ait POS Toplamı Var. Üzerine Yazılmadı.");if(old==null&&in.optInt("baseRevision")>0)throw new Exception("Düzenleme Kaydı Bulunamadı.");checkRevision(in,old);if(old!=null&&in.has("originalSavedAt")&&in.getLong("originalSavedAt")!=old.getLong("savedAt"))throw new Exception("Toplam Kaydı Değişti. Yeniden Açın.");if(debit!=null&&debit.getLong("amount")>r.getLong("total"))throw new Exception("Yeni Toplam Yatan Debit Tutarından Küçük Olamaz.");
   boolean moved=old!=null&&!original.equals(r.getString("id"));if(moved&&find(d,"pos_settlements",r.getString("id")+"_debit")!=null)throw new Exception("Hedef Tarihte Tahsilat Kaydı Var.");save(d,"pos_totals",r,old,in);if(moved){d.delete("pos_totals","id=?",new String[]{original});if(debit!=null){JSONObject linked=new JSONObject(debit.toString()).put("id",r.getString("id")+"_debit").put("totalId",r.getString("id")).put("transactionDate",r.getString("date")).put("previousTransactionDate",old.getString("date")).put("manualDateLink",!LocalDate.parse(debit.getString("bankDate")).minusDays(15).toString().equals(r.getString("date")));save(d,"pos_settlements",linked,debit,in);d.delete("pos_settlements","id=?",new String[]{debit.getString("id")});}}
   d.setTransactionSuccessful();return r;
  }finally{d.endTransaction();}
 }
 static JSONObject receive(CashDb db,String raw)throws Exception{JSONObject in=new JSONObject(raw);SQLiteDatabase d=db.getWritableDatabase();d.beginTransaction();try{JSONObject t=find(d,"pos_totals",in.getString("totalId"));if(t==null||in.getInt("totalRevision")!=t.getInt("revision")||in.getLong("totalSavedAt")!=t.getLong("savedAt"))throw new Exception("Toplam POS Kaydı Değişti. Tekrar Eşleştirin.");JSONObject debit=find(d,"pos_settlements",t.getString("id")+"_debit");if(debit!=null&&debit.optBoolean("manualDateLink",false))in.put("manualDateLink",true);else in.remove("manualDateLink");JSONObject r=settlement(in,t,debit),old=find(d,"pos_settlements",r.getString("id"));if(r.getString("kind").equals("credit")&&in.optInt("debitRevision")!=debit.getInt("revision"))throw new Exception("Debit Kaydı Değişti. Yeniden Eşleştirin.");checkRevision(in,old);save(d,"pos_settlements",r,old,in);d.setTransactionSuccessful();return r;}finally{d.endTransaction();}}
 static void merge(SQLiteDatabase d,JSONObject in,Set<String> known)throws Exception{JSONArray totals=in.optJSONArray("posTotals"),settlements=in.optJSONArray("settlements");if(totals!=null){if(totals.length()>20000)throw new Exception("POS Toplam Sınırı Aşıldı.");for(int i=0;i<totals.length();i++){JSONObject source=totals.getJSONObject(i),r=total(source);if(!known.contains(r.getString("cashId")))throw new Exception("Tanımsız POS Kasası.");if(find(d,"pos_totals",r.getString("id"))==null){ensureNoDetailed(d,r);r.put("revision",Math.max(1,source.optInt("revision",1))).put("savedAt",source.optLong("savedAt",System.currentTimeMillis())).put("reason",source.optString("reason","Yedekten Eklendi"));put(d,"pos_totals",r);}}}if(settlements!=null){if(settlements.length()>40000)throw new Exception("Tahsilat Sınırı Aşıldı.");for(int i=0;i<settlements.length();i++){JSONObject source=settlements.getJSONObject(i);JSONObject t=find(d,"pos_totals",source.getString("totalId"));if(t==null)throw new Exception("Tahsilatın POS Toplamı Yok.");JSONObject r=settlement(source,t,find(d,"pos_settlements",t.getString("id")+"_debit"));if(find(d,"pos_settlements",r.getString("id"))==null){r.put("revision",Math.max(1,source.optInt("revision",1))).put("savedAt",source.optLong("savedAt",System.currentTimeMillis())).put("reason",source.optString("reason","Yedekten Eklendi"));put(d,"pos_settlements",r);}}}}
 static void ensureNoDetailed(SQLiteDatabase d,JSONObject r)throws Exception{try(Cursor c=d.rawQuery("SELECT data FROM pos",null)){while(c.moveToNext()){JSONObject old=new JSONObject(c.getString(0));if(old.getString("cashId").equals(r.getString("cashId"))&&old.getString("date").equals(r.getString("date")))throw new Exception("Bu Kasa Ve Günde Ayrıntılı POS Kaydı Var. Aynı Tutar İkinci Kez Eklenemez.");}}}
 static void ensureNoTotal(SQLiteDatabase d,JSONObject r)throws Exception{if(find(d,"pos_totals",r.getString("cashId")+"_"+r.getString("date")+"_total")!=null)throw new Exception("Bu Kasa Ve Günde Tek Toplam POS Kaydı Var. İkinci Kez Eklenemez.");}
}
